<script>
(function(){
const html=document.documentElement,themeBtn=document.getElementById('themeBtn'),menuBtn=document.getElementById('menuBtn'),mainNav=document.getElementById('mainNav');
const saved=localStorage.getItem('worksitem-theme'),preferredDark=window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches,initial=saved||(preferredDark?'dark':'light');
html.setAttribute('data-theme',initial);themeBtn.textContent=initial==='dark'?'☀':'☾';
themeBtn.addEventListener('click',()=>{const next=html.getAttribute('data-theme')==='dark'?'light':'dark';html.setAttribute('data-theme',next);localStorage.setItem('worksitem-theme',next);themeBtn.textContent=next==='dark'?'☀':'☾'});
menuBtn.addEventListener('click',()=>{const open=mainNav.classList.toggle('open');menuBtn.setAttribute('aria-expanded',open?'true':'false');menuBtn.textContent=open?'×':'☰'});
mainNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mainNav.classList.remove('open');menuBtn.setAttribute('aria-expanded','false');menuBtn.textContent='☰'}));
document.querySelectorAll('.faq-q').forEach(btn=>btn.addEventListener('click',()=>{const item=btn.closest('.faq-item'),wasOpen=item.classList.contains('open');document.querySelectorAll('.faq-item').forEach(other=>{other.classList.remove('open');const icon=other.querySelector('.faq-q b');if(icon)icon.textContent='+'});if(!wasOpen){item.classList.add('open');btn.querySelector('b').textContent='−'}}));
})();
</script>
